SELECT (SELECT count(*) FROM public.cl_feeds WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e') feeds, (SELECT count(*) FROM public.cl_plans WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e') plans, (SELECT count(*) FROM public.cl_demands WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e') demands, (SELECT count(*) FROM public.cl_batches WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e') batches, (SELECT count(*) FROM public.cl_samples WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e') samples, (SELECT count(*) FROM public.cl_alerts WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e') alerts, (SELECT count(*) FROM public.cl_field_mappings WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e') fm, (SELECT count(*) FROM public.cl_value_mappings WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e') vm, (SELECT count(*) FROM public.cl_extra_fields WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e') xf, (SELECT count(*) FROM public.readers WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e' AND capture_source='carrier_scan') cl_readers, (SELECT count(*) FROM public.api_keys WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e') keys, (SELECT count(*) FROM public.one_db WHERE account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e' AND source='carrier') onedb_carrier, (SELECT count(*) FROM public.cl_feeds) feeds_all, (SELECT count(*) FROM public.cl_plans) plans_all;
